"""Short, source-linked introductions. Watching tips are editorial, not telemetry.

Biographies are paraphrased from F1's driver profiles, checked 2026-09-29.
No fixed driving technique is asserted where the source only describes a career.
"""
from copy import deepcopy


def _guide(slug: str, intro: str, character: str, watch: str) -> dict:
    return {"intro": intro, "character": character, "watch": watch,
            "source": f"https://www.formula1.com/en/drivers/{slug}",
            "checked_at": "2026-09-29",
            "note": "Краткая справка по официальной биографии. «На что смотреть» — редакционная подсказка, а не оценка телеметрии; стиль зависит от машины и условий."}


